@push('scripts')<script>const assistantForm=document.getElementById('assistant-form');assistantForm?.addEventListener('submit',async(e)=>{e.preventDefault();const input=document.getElementById('assistant-input'),box=document.getElementById('assistant-messages'),message=input.value.trim();if(!message)return;box.insertAdjacentHTML('beforeend','<div class="assistant-message assistant-question"></div>');box.lastElementChild.textContent=message;input.value='';const response=await fetch('{{ route('assistant.ask') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},body:JSON.stringify({message})});const data=await response.json();box.insertAdjacentHTML('beforeend','<div class="assistant-message assistant-answer"></div>');box.lastElementChild.textContent=data.reply||'{{ __('Try asking about tools, prompts, courses, or Kurdish AI.') }}';box.scrollTop=box.scrollHeight;});</script>@endpush
